"""Core of gitmini: object storage, index, commits, log, checkout.

All hashes are genuine git sha1s.  The framing is exactly git's:
``<kind> <byte-length> NUL <payload>``, zlib-compressed, stored at
``.gitmini/objects/<first 2 hex chars>/<remaining 38 hex chars>``.
"""

from __future__ import annotations

import hashlib
import json
import os
import time
import zlib
from typing import Dict, List, Optional, Tuple

# ---------------------------------------------------------------------------
# Errors


class GitMiniError(Exception):
    """Raised for all user-facing gitmini failures."""


# ---------------------------------------------------------------------------
# Repository layout

GITMINI_DIR = ".gitmini"


def repo_root(start: str = ".") -> str:
    """Walk upwards from *start* until a .gitmini directory is found."""
    path = os.path.abspath(start)
    while True:
        if os.path.isdir(os.path.join(path, GITMINI_DIR)):
            return path
        parent = os.path.dirname(path)
        if parent == path:
            raise GitMiniError(
                f"not a gitmini repository (no {GITMINI_DIR} in any parent of "
                f"{os.path.abspath(start)})"
            )
        path = parent


def objects_dir(root: str) -> str:
    return os.path.join(root, GITMINI_DIR, "objects")


def object_path(root: str, sha: str) -> str:
    return os.path.join(objects_dir(root), sha[:2], sha[2:])


def index_path(root: str) -> str:
    return os.path.join(root, GITMINI_DIR, "index.json")


def head_path(root: str) -> str:
    return os.path.join(root, GITMINI_DIR, "HEAD")


def ref_path(root: str, branch: str) -> str:
    return os.path.join(root, GITMINI_DIR, "refs", "heads", branch)


# ---------------------------------------------------------------------------
# Object read/write  (the heart of the content-addressed store)


def hash_object(data: bytes, kind: str = "blob", write: bool = False,
                root: str = ".") -> str:
    """Return the real git sha1 of ``kind + data``, optionally storing it."""
    if kind not in ("blob", "tree", "commit"):
        raise GitMiniError(f"unknown object kind: {kind!r}")
    store = b"%s %d\x00" % (kind.encode(), len(data)) + data
    sha = hashlib.sha1(store).hexdigest()
    if write:
        path = object_path(root, sha)
        if not os.path.exists(path):  # content-addressed => write-once
            os.makedirs(os.path.dirname(path), exist_ok=True)
            tmp = path + ".tmp%d" % os.getpid()
            with open(tmp, "wb") as fh:
                fh.write(zlib.compress(store))
            os.replace(tmp, path)
    return sha


def read_object(root: str, sha: str) -> Tuple[str, bytes]:
    """Load a loose object, verifying its hash on the way out.

    Returns ``(kind, payload_bytes)`` where payload excludes the header.
    """
    if not _is_hex(sha) or len(sha) not in (40,):
        raise GitMiniError(f"not a valid object id: {sha!r}")
    path = object_path(root, sha)
    if not os.path.exists(path):
        raise GitMiniError(f"object not found: {sha}")
    with open(path, "rb") as fh:
        raw = zlib.decompress(fh.read())
    header, _, payload = raw.partition(b"\x00")
    kind_b, _, size_b = header.partition(b" ")
    kind = kind_b.decode()
    if int(size_b) != len(payload):
        raise GitMiniError(f"corrupt object {sha}: size mismatch")
    if hashlib.sha1(raw).hexdigest() != sha:
        raise GitMiniError(f"corrupt object {sha}: hash mismatch")
    return kind, payload


def _is_hex(s: str) -> bool:
    try:
        int(s, 16)
        return True
    except ValueError:
        return False


def write_blob(root: str, data: bytes) -> str:
    return hash_object(data, "blob", write=True, root=root)


# ---------------------------------------------------------------------------
# init / index (staging area)


def init(path: str = ".") -> str:
    root = os.path.abspath(path)
    os.makedirs(objects_dir(root), exist_ok=True)
    os.makedirs(ref_path(root, ""), exist_ok=True)
    hp = head_path(root)
    if not os.path.exists(hp):
        with open(hp, "w") as fh:
            fh.write("ref: refs/heads/main\n")
    ip = index_path(root)
    if not os.path.exists(ip):
        write_index(root, {})
    return root


def load_index(root: str) -> Dict[str, dict]:
    """The index maps worktree path -> {'mode': '100644'|'100755', 'sha': hex}."""
    with open(index_path(root)) as fh:
        return json.load(fh)


def write_index(root: str, index: Dict[str, dict]) -> None:
    entries = {p: index[p] for p in sorted(index)}
    with open(index_path(root), "w") as fh:
        json.dump(entries, fh, indent=1, sort_keys=True)
        fh.write("\n")


def _file_mode(st_mode: int) -> str:
    return "100755" if st_mode & 0o111 else "100644"


def add_paths(root: str, paths: List[str]) -> List[str]:
    """Hash and store blobs for *paths*, updating the index. Returns shas."""
    index = load_index(root)
    written = []
    seen = set()
    for given in paths:
        base = os.path.abspath(given)
        if os.path.isdir(base):
            for dirpath, dirnames, filenames in os.walk(base):
                dirnames[:] = [d for d in sorted(dirnames)
                               if d != GITMINI_DIR and d != ".git"]
                for name in sorted(filenames):
                    full = os.path.join(dirpath, name)
                    rel = os.path.relpath(full, root).replace(os.sep, "/")
                    if rel in seen:
                        continue
                    seen.add(rel)
                    written.append(_add_file(root, index, full, rel))
        elif os.path.isfile(base):
            rel = os.path.relpath(base, root).replace(os.sep, "/")
            if rel not in seen:
                seen.add(rel)
                written.append(_add_file(root, index, base, rel))
        else:
            raise GitMiniError(f"pathspec {given!r} did not match any files")
    write_index(root, index)
    return written


