    with open(full, "rb") as fh:
        data = fh.read()
    mode = _file_mode(os.stat(full).st_mode)
    sha = hash_object(data, "blob", write=True, root=root)
    index[rel] = {"mode": mode, "sha": sha}
    return sha


# ---------------------------------------------------------------------------
# Trees: build nested tree objects bottom-up from the flat index


def write_tree(root: str) -> str:
    """Write all necessary tree objects for the current index; return root sha."""
    index = load_index(root)
    return write_tree_from_index(root, index)


def write_tree_from_index(root: str,
                          index: Dict[str, dict]) -> str:  # noqa: C901
    # Build a nested trie: {"src": {"core.py": ("100644", sha)}, ...}
    trie: dict = {}
    for path, entry in index.items():
        parts = path.split("/")
        node = trie
        for part in parts[:-1]:
            node = node.setdefault(part, {})
            if not isinstance(node, dict):
                raise GitMiniError(f"index conflict at {path!r}")
        node[parts[-1]] = (entry["mode"], entry["sha"])

    def emit(node: dict, prefix: str) -> str:
        rows = []
        for name, value in node.items():
            if isinstance(value, dict):
                sub_sha = emit(value, prefix + name + "/")
                rows.append((name.encode(), b"40000", sub_sha))
            else:
                mode, sha = value
                rows.append((name.encode(), mode.encode(), sha))
        # Git's tree sort: names compared as bytes, directories as if
        # suffixed with '/'.
        rows.sort(key=lambda r: r[0] + (b"/" if r[1] == b"40000" else b""))
        payload = b"".join(
            mode + b" " + name + b"\x00" + bytes.fromhex(sha)
            for name, mode, sha in rows
        )
        return hash_object(payload, "tree", write=True, root=root)

    return emit(trie, "")


# ---------------------------------------------------------------------------
# Commits


def create_commit(root: str, message: str, parent: Optional[str],
                  tree_sha: Optional[str] = None,
                  name: str = "gitmini",
                  email: str = "gitmini@example.com",
                  timestamp: Optional[int] = None,
                  tz: str = "+0000") -> str:
    if tree_sha is None:
        tree_sha = write_tree(root)
    ts = int(time.time()) if timestamp is None else int(timestamp)
    ident = f"{name} <{email}> {ts} {tz}"
    lines = [f"tree {tree_sha}"]
    if parent:
        lines.append(f"parent {parent}")
    lines += [f"author {ident}", f"committer {ident}", "", message.rstrip("\n")]
    payload = ("\n".join(lines) + "\n").encode()
    return hash_object(payload, "commit", write=True, root=root)


def parse_commit(payload: bytes) -> dict:
    header, _, body = payload.partition(b"\n\n")
    info = {"parents": [], "message": body.decode()}
    for line in header.decode().splitlines():
        key, _, value = line.partition(" ")
        if key == "tree":
            info["tree"] = value
        elif key == "parent":
            info["parents"].append(value)
        elif key in ("author", "committer"):
            info[key] = value
    return info


# ---------------------------------------------------------------------------
# Refs / history traversal


def current_branch(root: str) -> str:
    with open(head_path(root)) as fh:
        head = fh.read().strip()
    prefix = "ref: refs/heads/"
    if not head.startswith(prefix):
        raise GitMiniError("detached HEAD not supported by gitmini")
    return head[len(prefix):]


