        objdir = object_path(root, refish)
        if os.path.exists(objdir):
            kind, _ = read_object(root, refish)
            if kind == "commit":
                return refish
            raise GitMiniError(
                f"object {refish} is a {kind}, not a commit")
    elif 4 <= len(refish) < 40 and _is_hex(refish):
        matches = []
        fan = os.path.join(objects_dir(root), refish[:2])
        if os.path.isdir(fan):
            for rest in sorted(os.listdir(fan)):
                cand = refish[:2] + rest
                if cand.startswith(refish):
                    matches.append(cand)
        if len(matches) == 1:
            return resolve(root, matches[0])
        if len(matches) > 1:
            raise GitMiniError(f"ambiguous abbreviated id: {refish!r}")
    raise GitMiniError(f"unknown revision: {refish!r}")


def head_commit(root: str) -> Optional[str]:
    branch = current_branch(root)
    rp = ref_path(root, branch)
    if not os.path.exists(rp):
        return None
    with open(rp) as fh:
        return fh.read().strip()


def commit_chain(root: str, start: Optional[str] = None) -> List[Tuple[str, dict]]:
    """Follow first-parent links from *start* (default HEAD) back to the root.

    Returns ``[(sha, parsed_commit), ...]``, newest first.
    """
    chain: List[Tuple[str, dict]] = []
    sha = head_commit(root) if start is None else resolve(root, start)
    seen = set()
    while sha is not None:
        if sha in seen:
            raise GitMiniError(f"cycle detected at {sha}")
        seen.add(sha)
        kind, payload = read_object(root, sha)
        if kind != "commit":
            raise GitMiniError(f"{sha} is a {kind}, not a commit")
        info = parse_commit(payload)
        chain.append((sha, info))
        sha = info["parents"][0] if info["parents"] else None
    return chain


