# checkout-file: restore one blob from an old commit


def find_path_in_commit(root: str, commit_sha: str, path: str) -> str:
    """Return the blob sha for *path* in the tree of *commit_sha*."""
    kind, payload = read_object(root, commit_sha)
    if kind != "commit":
        raise GitMiniError(f"{commit_sha} is a {kind}, not a commit")
    tree_sha = parse_commit(payload)["tree"]

    parts = [p for p in path.split("/") if p]
    for i, part in enumerate(parts):
        kind, payload = read_object(root, tree_sha)
        if kind != "tree":
            raise GitMiniError(f"path {path!r}: {part!r} is not a directory")
        last = i == len(parts) - 1
        found = None
        offset = 0
        while offset < len(payload):
            nul = payload.index(b"\x00", offset)
            mode_b, name_b = payload[offset:nul].split(b" ", 1)
            sha_hex = payload[nul + 1:nul + 21].hex()
            if name_b.decode() == part:
                found = (mode_b.decode(), sha_hex)
                break
            offset = nul + 21
        if found is None:
            raise GitMiniError(f"path not found in commit {commit_sha}: {path!r}")
        mode, sha_hex = found
        tree_sha = sha_hex  # next loop iteration reads it (or we're done)
    if mode == "40000":
        raise GitMiniError(f"path {path!r} is a directory, not a file")
    return sha_hex


def checkout_file(root: str, refish: str, path: str, out: Optional[str] = None) -> str:
    """Restore *path* from *refish* into the working tree. Returns dest path."""
    commit_sha = resolve(root, refish)
    blob_sha = find_path_in_commit(root, commit_sha, path)
    kind, data = read_object(root, blob_sha)
    if kind != "blob":
        raise GitMiniError(f"expected blob for {path!r}, got {kind}")
    dest = os.path.join(root, out or path)
    os.makedirs(os.path.dirname(dest) or ".", exist_ok=True)
    with open(dest, "wb") as fh:
        fh.write(data)
    return dest

